     1	package hotel.reservations;
     2	
     3	import hotel.rooms.Room;
     4	import java.math.BigDecimal;
     5	import java.math.RoundingMode;
     6	import java.time.LocalDate;
     7	import java.time.Month;
     8	
     9	/**
    10	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
    11	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
    12	 * (half-even) at every step.
    13	 */
    14	public final class PriceCalculator {
    15	
    16	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
    17	
    18	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan, String companyCode) {
    19	        return RatePlanStrategies.get(ratePlan).calculate(room, checkIn, checkOut, companyCode);
    20	    }
    21	
    22	    public void validate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan, String companyCode) {
    23	        RatePlanStrategies.get(ratePlan).validate(room, checkIn, checkOut, companyCode);
    24	    }
    25	
    26	    /** The sum of all nights in the stay, each priced at the room's nightly rate plus high-season surcharge. */
    27	    static BigDecimal sumNights(Room room, LocalDate checkIn, LocalDate checkOut) {
    28	        BigDecimal sum = cents(BigDecimal.ZERO);
    29	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    30	            sum = sum.add(nightPrice(room, night));
    31	        }
    32	        return sum;
    33	    }
    34	
    35	    static BigDecimal nightPrice(Room room, LocalDate night) {
    36	        BigDecimal nightlyRate = room.nightlyRate();
    37	        if (isHighSeason(night)) {
    38	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
    39	        }
    40	        return cents(nightlyRate);
    41	    }
    42	
    43	    static int countNights(LocalDate checkIn, LocalDate checkOut) {
    44	        return (int) checkIn.datesUntil(checkOut).count();
    45	    }
    46	
    47	    /** High season: from December 15 to the end of February, and the whole of July. */
    48	    static boolean isHighSeason(LocalDate date) {
    49	        Month month = date.getMonth();
    50	        return month == Month.JANUARY
    51	                || month == Month.FEBRUARY
    52	                || month == Month.JULY
    53	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
    54	    }
    55	
    56	    static BigDecimal cents(BigDecimal value) {
    57	        return value.setScale(2, RoundingMode.HALF_EVEN);
    58	    }
    59	}
