163	     9	/**
164	    10	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
165	    11	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
166	    12	 * (half-even) at every step.
167	    13	 */
168	    14	public final class PriceCalculator {
169	    15	
170	    16	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
171	    17	
172	    18	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan, String companyCode) {
173	    19	        return RatePlanStrategies.get(ratePlan).calculate(room, checkIn, checkOut, companyCode);
174	    20	    }
175	    21	
176	    22	    public void validate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan, String companyCode) {
177	    23	        RatePlanStrategies.get(ratePlan).validate(room, checkIn, checkOut, companyCode);
178	    24	    }
179	    25	
180	    26	    /** The sum of all nights in the stay, each priced at the room's nightly rate plus high-season surcharge. */
181	    27	    static BigDecimal sumNights(Room room, LocalDate checkIn, LocalDate checkOut) {
182	    28	        BigDecimal sum = cents(BigDecimal.ZERO);
183	    29	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
184	    30	            sum = sum.add(nightPrice(room, night));
185	    31	        }
186	    32	        return sum;
187	    33	    }
188	    34	
189	    35	    static BigDecimal nightPrice(Room room, LocalDate night) {
190	    36	        BigDecimal nightlyRate = room.nightlyRate();
191	    37	        if (isHighSeason(night)) {
192	    38	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
193	    39	        }
194	    40	        return cents(nightlyRate);
195	    41	    }
196	    42	
197	    43	    static int countNights(LocalDate checkIn, LocalDate checkOut) {
198	    44	        return (int) checkIn.datesUntil(checkOut).count();
199	    45	    }
200	    46	
201	    47	    /** High season: from December 15 to the end of February, and the whole of July. */
202	    48	    static boolean isHighSeason(LocalDate date) {
203	    49	        Month month = date.getMonth();
204	    50	        return month == Month.JANUARY
205	    51	                || month == Month.FEBRUARY
206	    52	                || month == Month.JULY
207	    53	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
208	    54	    }
209	    55	
210	    56	    static BigDecimal cents(BigDecimal value) {
211	    57	        return value.setScale(2, RoundingMode.HALF_EVEN);
212	    58	    }
