    10	/** Weekend package: Friday to Sunday, fixed price by room type, half refund on cancellation. */
    11	final class WeekendPackageRatePlanStrategy implements RatePlanStrategy {
    12	
    13	    private static final Map<RoomType, BigDecimal> PACKAGE_PRICES = Map.of(
    14	            RoomType.STANDARD, new BigDecimal("520.00"),
    15	            RoomType.DELUXE, new BigDecimal("820.00"),
    16	            RoomType.SUITE, new BigDecimal("1200.00"));
