    18	    @Override
    19	    public void validate(Room room, LocalDate checkIn, LocalDate checkOut, String companyCode) {
    20	        if (checkIn.getDayOfWeek() != DayOfWeek.FRIDAY) {
    21	            throw new HotelException(
    22	                    ErrorCode.INVALID_REQUEST, "weekend package requires check-in on Friday");
    23	        }
    24	        if (checkOut.getDayOfWeek() != DayOfWeek.SUNDAY) {
    25	            throw new HotelException(
    26	                    ErrorCode.INVALID_REQUEST, "weekend package requires check-out on Sunday");
    27	        }
    28	        if (PriceCalculator.countNights(checkIn, checkOut) != 2) {
    29	            throw new HotelException(
    30	                    ErrorCode.INVALID_REQUEST, "weekend package is exactly two nights (Friday to Sunday)");
    31	        }
    32	    }
