    34	    @Override
    35	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, String companyCode) {
    36	        BigDecimal packagePrice = PACKAGE_PRICES.get(room.type());
    37	        return new Price(2, packagePrice, PriceCalculator.cents(BigDecimal.ZERO), packagePrice);
